export function getApollo11Elevation(x: number, z: number): number {
  const gx = Math.max(0, Math.min(APLLO_W - 1, ((x + 100) / 200) * (APLLO_W - 1)));
  const gz = Math.max(0, Math.min(APLLO_H - 1, ((z + 100) / 200) * (APLLO_H - 1)));
  const x0 = Math.floor(gx);
  const x1 = Math.min(APLLO_W - 1, x0 + 1);
  const z0 = Math.floor(gz);
  const z1 = Math.min(APLLO_H - 1, z0 + 1);
  const fx = gx - x0;
  const fz = gz - z0;
  const h00 = APOLLO11_HEIGHTS[z0 * APLLO_W + x0] ?? -0.5;
  const h10 = APOLLO11_HEIGHTS[z0 * APLLO_W + x1] ?? -0.5;
  const h01 = APOLLO11_HEIGHTS[z1 * APLLO_W + x0] ?? -0.5;
  const h11 = APOLLO11_HEIGHTS[z1 * APLLO_W + x1] ?? -0.5;
  return (h00 * (1 - fx) + h10 * fx) * (1 - fz) + (h01 * (1 - fx) + h11 * fx) * fz;
}
const APLLO_W = APOLLO11_GRID_W;
const APLLO_H = APOLLO11_GRID_H;
